SELECT "THREADS"."HOST" AS HOST,"THREADS"."PORT" AS PORT,"THREADS"."SERVICE_NAME" AS SERVICE_NAME,"THREADS"."HIERARCHY" AS HIERARCHY,"THREADS"."CONNECTION_ID" AS CONNECTION_ID,"THREADS"."THREAD_ID" AS THREAD_ID,"THREADS"."THREAD_TYPE" AS THREAD_TYPE,"THREADS"."THREAD_METHOD" AS THREAD_METHOD,"THREADS"."THREAD_DETAIL" AS THREAD_DETAIL,"THREADS"."DURATION" AS DURATION,"THREADS"."CALLER" AS CALLER,"THREADS"."CALLING" AS CALLING,"THREADS"."USER_NAME" AS USER_NAME,"THREADS"."APPLICATION_USER_NAME" AS APPLICATION_USER_NAME,"THREADS"."CPU_TIME_SELF" AS CPU_TIME_SELF,"THREADS"."CPU_TIME_CUMULATIVE" AS CPU_TIME_CUMULATIVE,"THREADS"."THREAD_STATE" AS THREAD_STATE,"THREADS"."TRANSACTION_ID" AS T5_TRANSACTION_ID,"THREADS"."UPDATE_TRANSACTION_ID" AS UPDATE_TRANSACTION_ID,"CONN"."TRANSACTION_ID" AS T6_TRANSACTION_ID,"CONN"."START_TIME" AS START_TIME,"CONN"."IDLE_TIME" AS IDLE_TIME,"CONN"."CONNECTION_STATUS" AS CONNECTION_STATUS,"CONN"."CLIENT_HOST" AS CLIENT_HOST,"CONN"."CLIENT_IP" AS CLIENT_IP,"CONN"."CLIENT_PID" AS CLIENT_PID,"CONN"."CONNECTION_TYPE" AS CONNECTION_TYPE,"CONN"."OWN" AS OWN,"CONN"."IS_HISTORY_SAVED" AS IS_HISTORY_SAVED,"CONN"."MEMORY_SIZE_PER_CONNECTION" AS MEMORY_SIZE_PER_CONNECTION,"CONN"."AUTO_COMMIT" AS AUTO_COMMIT,"CONN"."LAST_ACTION" AS LAST_ACTION,"CONN"."CURRENT_STATEMENT_ID" AS CURRENT_STATEMENT_ID,"CONN"."CURRENT_OPERATOR_NAME" AS CURRENT_OPERATOR_NAME,"CONN"."FETCHED_RECORD_COUNT" AS FETCHED_RECORD_COUNT,"CONN"."SENT_MESSAGE_SIZE" AS SENT_MESSAGE_SIZE,"CONN"."SENT_MESSAGE_COUNT" AS SENT_MESSAGE_COUNT,"CONN"."RECEIVED_MESSAGE_SIZE" AS RECEIVED_MESSAGE_SIZE,"CONN"."RECEIVED_MESSAGE_COUNT" AS RECEIVED_MESSAGE_COUNT,"CONN"."CREATOR_THREAD_ID" AS CREATOR_THREAD_ID,"CONN"."CREATED_BY" AS CREATED_BY,"CONN"."IS_ENCRYPTED" AS IS_ENCRYPTED,"CONN"."END_TIME" AS END_TIME,"BLOCKED"."BLOCKED_TRANSACTION_ID" AS BLOCKED_TRANSACTION_ID,"BLOCKED"."BLOCKED_UPDATE_TRANSACTION_ID" AS BLOCKED_UPDATE_TRANSACTION_ID,"BLOCKED"."LOCK_OWNER_TRANSACTION_ID" AS LOCK_OWNER_TRANSACTION_ID,"BLOCKED"."LOCK_OWNER_UPDATE_TRANSACTION_ID" AS LOCK_OWNER_UPDATE_TRANSACTION_ID,"BLOCKED"."BLOCKED_TIME" AS BLOCKED_TIME,"BLOCKED"."WAITING_RECORD_ID" AS WAITING_RECORD_ID,"BLOCKED"."WAITING_SCHEMA_NAME" AS WAITING_SCHEMA_NAME,"BLOCKED"."LOCK_TYPE" AS LOCK_TYPE,"BLOCKED"."LOCK_MODE" AS LOCK_MODE,"TRANS1"."HOST" AS T1_HOST,"TRANS1"."PORT" AS T1_PORT,"TRANS1"."TRANSACTION_ID" AS T1_TRANSACTION_ID,"TRANS2"."TRANSACTION_ID" AS T2_TRANSACTION_ID,"TRANS3"."CONNECTION_ID" AS T3_CONNECTION_ID,"TRANS4"."HOST" AS T4_HOST,"TRANS4"."PORT" AS T4_PORT,"TRANS4"."TRANSACTION_ID" AS T4_TRANSACTION_ID,"TRANS4"."CONNECTION_ID" AS T4_CONNECTION_ID,"BLOCKED"."WAITING_OBJECT_NAME" AS WAITING_OBJECT_NAME,"BLOCKED"."WAITING_OBJECT_TYPE" AS WAITING_OBJECT_TYPE,"THREADS"."LOCK_WAIT_COMPONENT" AS LOCK_WAIT_COMPONENT,"THREADS"."LOCK_WAIT_NAME" AS LOCK_WAIT_NAME,"THREADS"."LOCK_OWNER_THREAD_ID" AS LOCK_OWNER_THREAD_ID 
from public.m_service_threads as threads 
left outer join m_connections as conn on threads.connection_id = conn.connection_id 
left outer join m_blocked_transactions as blocked on conn.transaction_id =  
	(select transaction_id from m_transactions where update_transaction_id = blocked.blocked_update_transaction_id and transaction_type = 'USER TRANSACTION') 
left outer join m_transactions as trans1 on (trans1.update_transaction_id = blocked.lock_owner_update_transaction_id and trans1.transaction_type = 'USER TRANSACTION') 
left outer join m_transactions as trans2 on (trans2.update_transaction_id = blocked.blocked_update_transaction_id and trans2.transaction_type = 'USER TRANSACTION') 
left outer join m_transactions as trans3 on (trans3.update_transaction_id = blocked.lock_owner_update_transaction_id and trans3.host = blocked.host and trans3.transaction_id = blocked.lock_owner_transaction_id and trans3.transaction_type = 'EXTERNAL TRANSACTION') 
left outer join m_transactions as trans4 on (trans4.update_transaction_id = blocked.blocked_update_transaction_id and trans4.transaction_id = blocked.blocked_transaction_id and trans4.host = blocked.host and trans4.port = blocked.port  and trans4.transaction_type = 'EXTERNAL TRANSACTION') 
where ((THREAD_STATE != 'Inactive'))
and duration > 1000
and service_name = 'indexserver'
and thread_type != 'SystemReplicationAsyncLogSender'
and thread_type != 'JobWorker';



SELECT * FROM _sys_statistics.HOST_UNCOMMITTED_WRITE_TRANSACTION where server_timestamp >= '2020-09-30 00:00:00'
order by server_timestamp desc